e-4b0e-ba35-f6233f98814e/file-preview)![image](http://192.168.110.16:3080/files/146e3d7c-2b8d-4d9e-9076-f4a052c32154/file-preview)![image](http://192.168.110.16:3080/files/611820d3-d044-4892-89bc-def64842d352/file-preview)![image](http://192.16',NULL,NULL,'fd51ffdf545c72f443f750822706be9846984746dbddeac69b1f3cd60b8c762b','2026-08-12 09:22:17'),(79,4,'4a1a8bb6-9746-4108-8d9c-b8d7d74479be',30,'TEXT','c-def64842d352/file-preview)![image](http://192.168.110.16:3080/files/828c91e5-d2b7-4c3d-855b-126adebba536/file-preview)![image](http://192.168.110.16:3080/files/65c1ec08-ebf8-4ba3-8836-72f76c9867bf/file-preview)',NULL,NULL,'92f7f510de6d0731ffba88ccdba6bc97b68aeed51539a0c9d68949bf66dbd957','2026-08-12 09:22:17'),(80,5,'afa10513-cc98-4f85-bfe0-76b78200d9d0',1,'TEXT','肠道菌群检测服务流程',NULL,NULL,'9b96fdfa481c89764a667745a73161a06a7a668bc27549a41df94d627c2f25b8','2026-08-14 02:39:19'),(81,5,'32572c6c-531c-402d-bd8d-2f840177ed65',2,'TEXT','一、下单与采样盒寄送\n1. 用户下单后，我们会在 1-2 个工作日内寄出采样盒，内含采样管、一次性手套、采集说明书和回寄袋。\n2. 收到采样盒后，请按说明书采集粪便样本，采样量以覆盖采样管刻度线为宜。\n3. 采样完成后，将采样管放回回寄袋，按说明书密封。',NULL,NULL,'ed2a15c116a4c0a5b530aa87001fac9254b0c17b92bb05e0a87b6346b7609513','2026-08-14 02:39:19'),(82,5,'0056b0af-3622-4e3a-ba5c-9b8071957f7d',3,'TEXT','二、样本回寄\n1. 建议采样后当天回寄，避免样本在常温下放置过久。\n2. 回寄时使用盒内附带的顺丰到付回寄袋，无需用户承担运费。\n3. 实验室收到样本后会短信/公众号推送确认。',NULL,NULL,'7c53e8e9a1c35c541e491e0ebd227f01ea1289cedc338a225bc876def611f2c6','2026-08-14 02:39:19'),(83,5,'e779a280-72fd-411f-b33d-52080b53894b',4,'TEXT','三、检测周期\n- 样本到达实验室后，**7-10 个工作日**出具检测报告。\n- 检测高峰期可能顺延 1-2 个工作日，公众号会有进度提示。',NULL,NULL,'6fd3d9ec416667617f8fc1d4914e2cd978f07d17199a4fe038de7d58d047f0ef','2026-08-14 02:39:19'),(84,5,'f79eb47a-2c69-4fc5-9ed3-02b8c03fe2bc',5,'TEXT','四、报告解读\n1. 报告包含肠道菌群多样性、有益菌/有害菌丰度、与常见疾病相关的菌属提示等内容。\n2. 报告中所有指标均为**科普性解读**，不构成疾病诊断。\n3. 如有疑问，可在报告页联系专属健康顾问，或拨打客服热线。',NULL,NULL,'b93bf9b0fb69771cca944efb1417d58430b7615c6b9ecd0b9edbdc285b716b8f','2026-08-14 02:39:19'),(85,6,'545cf9d2-605e-4b38-be42-aadbb97e01dc',1,'TEXT','第 1 页',NULL,NULL,'8f1e2af07c9ff5867f0f6b1afb06fd637dbe22efacea3c65df63cf8a35d549bc','2026-08-14 06:03:12'),(86,6,'960d5911-a8d0-4e47-8af1-cbc8f9949e28',2,'TEXT','肠道菌群检测产品介绍\n本产品通过粪便样本分析肠道菌群组成，采样后 7 个工作日出具报告。\n\n| 指标 | 说明 |\n| --- | --- |\n| 采样 | 粪便采样盒 |\n| 报告 | 7 个工作日 |',NULL,NULL,'61d9fdae3019c2fc2105c0c2ce64bfcf7019a151be4de9b17120666153ad122d','2026-08-14 06:03:12'),(87,6,'208d3791-bb61-4ceb-8f31-07422266f9b1',3,'TEXT','第 2 页\n![第2页图片1](sample_assets/img-001.png)\n\n> 【图片文字】菌群丰度：拟杆菌门42%，厚壁菌门38%，放线菌门12%\n\n> 讲解：菌群丰度占比是报告核心指标。',NULL,NULL,'56e9509ef2266329e25582a8e214be2f258d09a3a0846b83acb5bfc6f4f83c01','2026-08-14 06:03:12'),(88,7,'c5ac65c0-02b5-4db3-a87d-8cc9a923d6c6',1,'TEXT','![chart_text](chart_text_assets/img-001.png)\n\n> 【图片文字】菌群丰度：拟杆菌门42%，厚壁菌门38%，放线菌门12%',NULL,NULL,'21ab603c2e164d54d2081092800f9bce441369d9d3523a34efbd01df6ad62f29','2026-08-14 06:05:10'),(89,8,'7a3a3a6e-8be6-4127-b1cd-eba8705e3419',1,'TEXT','Native PDF: 肠道菌群检测说明\n本 PDF 含文本层，可直接提取。采样后 7 个工作日出具报告。',NULL,NULL,'610d36c02d5916c28dc855dbf3344da95417a78dc8d9ec315bae51bbb5cddfb8','2026-08-14 06:05:17'),(90,9,'0a2acd80-ff86-4cb9-aa18-b150a11fe6aa',1,'TEXT','![第1页（扫描件）](scanned_assets/img-001.png)\n\n> 【图片文字】菌群丰度：拟杆菌门42%，厚壁菌门38%，放线菌门12%',NULL,NULL,'302bc92f409cbe2f50d8400f1fba2dab70697715305c53a9a8cd5e2cb33d7c28','2026-08-14 06:05:24'),(91,10,'20aed65f-2af5-4b1c-adc2-1c8f4dab5fb8',1,'TEXT','DOCX 测试文档\n这是一个 Word 文档，用于验证 markitdown 转换。\n\n| | |\n| --- | --- |\n| 项目 | 说明 |\n| 采样 | 粪便采样盒 |',NULL,NULL,'940dfc71a25ef7299359a226644d36331817bc922c9693666ca1a31a4ee1b6bb','2026-08-14 06:05:31'),(92,11,'8dd4b8ad-8481-4bcf-b2fc-ce915bd26d03',1,'QA','肠道菌群检测服务流程是什么？','肠道菌群检测服务流程是什么？','完整流程包括：①下单后1-2个工作日内寄出采样盒，收到后按说明采集样本并密封；②采样当天使用盒内顺丰到付回寄袋寄回（无需承担运费），实验室收到后推送确认；③样本到达实验室后7-10个工作日出具报告（高峰期顺延1-2天）；④报告提供菌群多样性与丰度科普解读（非疾病诊断），如有疑问可在报告页联系专属健康顾问或客服热线。','aa32710bbaa92ba75ccceca697b560cb536e1c50f5dcea4b83f0b255ece4b52d','2026-08-17 03:41:49'),(93,11,'6ef001e5-2f13-45ce-bd4f-8a51ae34fac5',2,'QA','检测流程具体有哪些步骤？','检测流程具体有哪些步骤？','检测步骤为：下单寄送采样盒→用户采集并密封样本→顺丰到付回寄→实验室接收确认→7-10个工作日出具报告→报告科普解读及客服支持。','5c5accf131c4ff88ecd68b4408f53f86de699ee672377c7d9d60cc40623efb2d','2026-08-17 03:41:49'),(94,11,'a5a87e8d-c2ee-45b0-84e4-68019f4e973e',3,'QA','怎么做检测？','怎么做检测？','先下单获取采样盒，收到后按说明采集粪便样本并密封，通过盒内顺丰到付回寄袋免费寄回实验室，等待7-10个工作日出具报告，最后在报告页查看菌群多样性与丰度的科普解读。','0cd030b3e8f97494644fef0ee4fa43ea9f6c3ab5f0490d7df762185a559249aa','2026-08-17 03:41:49'),(95,11,'36470bee-b573-4189-8507-c90d99cc73e7',4,'QA','检测要多久？','检测要多久？','样本到达实验室后需7-10个工作日出具报告，高峰期可能顺延1-2天；采样盒下单后1-2个工作日内寄出，样本回寄后实验室会推送确认。','070022f12f30dd9180d46b2df15007acb274f8f4a8650b2fd5463e4c2135887a','2026-08-17 03:41:49'),(96,11,'c4eb9964-d8ac-4c5e-809e-8d75898d99d5',5,'QA','样本如何回寄？','样本如何回寄？','采样后建议当天使用采样盒内的顺丰到付回寄袋寄回，无需承担运费；实验室收到样本后会推送确认通知。','c2b9381490cb49d03750da47912ce8f0d96d5ae612cdf941aa2e9a56229125e5','2026-08-17 03:41:49'),(97,11,'2131d4f6-4030-46b8-abf3-7a45c87d591e',6,'QA','报告如何解读？','报告如何解读？','报告提供菌群多样性与丰度的科普解读，但非疾病诊断；如有疑问可在报告页联系专属健康顾问或拨打客服热线咨询。','3883c5963cb3eea222ed51cdf5d35e6867f2c8c4a9f7399be5a523c85ee6acf9','2026-08-17 03:41:49'),(98,11,'6d35d860-516c-41fa-ac44-023240165e96',7,'QA','检测服务需要付费回寄吗？','检测服务需要付费回寄吗？','不需要。采样盒内含顺丰到付回寄袋，用户回寄样本时无需承担运费。','897ae35a3a83caaa58d64ff5d99e44625d46b5522acda5baea53991299051f5d','2026-08-17 03:41:49'),(99,11,'24b568b9-e67e-4942-8d9a-78164fb47626',8,'QA','采样盒什么时候寄出？','采样盒什么时候寄出？','下单后1-2个工作日内寄出采样盒，用户收到后即可按说明采集样本并密封。','4855c328622fdd879cd6340315128c9815e6443c9e266407ab406aabb9b17ac5','2026-08-17 03:41:49'),(100,12,'b616c0d6-6517-474e-9919-17bec0f21a05',1,'TEXT','富玛特--提供菌群移植整套解决方案的服务商\n北京富玛特生物科技有限公司菌群移植事业目前取得的成就，欢迎洽谈粪菌移植市场合作',NULL,NULL,'60e7204b4c0f7ee2486df752b3892ec53ad0415101ff6ef79659ff5ccfc32bfa','2026-08-18 03:52:22'),(101,12,'ef9254fd-809c-4f3b-a270-609c3d75a5b9',2,'TEXT','- \n ## 菌群移植临床应用系列培训 | 给药途径怎么选？供体筛查到术后养护的标准化流程怎么做？这期课程一次性讲透！菌群移植(FMT)技术已被国家卫健委纳入医疗服务收费目录，818条例明确其为成熟临床技术。然而，给药途径怎么选?术后不良反应怎么处理?全链条操作标准是什么?如何根据患者具...\n- \n ## 为什么高净值人群都在选择富玛特肠菌快检？ 五大维度120项指标，1个工作日即可出报告常年商务应酬、熬夜承压、三餐作息紊乱，已经成为众多企业家、高净值人群的日常常态。脂肪肝、顽固性失眠、高尿酸、情绪焦虑、肠胃反复不适接踵而至。对中年企业家