CREATE TABLE `core_dify_publish_targets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `version_id` int NOT NULL,
  `dataset_id` varchar(255) NOT NULL,
  `pipeline_start_node_id` varchar(128) DEFAULT NULL,
  `pipeline_version` varchar(64) NOT NULL DEFAULT 'default',
  `dify_file_id` varchar(255) DEFAULT NULL,
  `pipeline_run_id` varchar(255) DEFAULT NULL,
  `dify_document_id` varchar(255) DEFAULT NULL,
  `status` enum('NOT_SYNCED','QUEUED','RUNNING','INDEXING','COMPLETED','FAILED','DELETE_PENDING','DELETED') NOT NULL DEFAULT 'NOT_SYNCED',
  `attempts` int NOT NULL DEFAULT '0',
  `last_error` text,
  `run_output` json DEFAULT NULL,
  `indexed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_core_dify_publish_targets_id` (`id`),
  KEY `ix_core_dify_publish_targets_version_id` (`version_id`),
  KEY `ix_core_dify_publish_targets_status` (`status`),
  CONSTRAINT `core_dify_publish_targets_ibfk_1` FOREIGN KEY (`version_id`) REFERENCES `core_knowledge_document_versions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
