-- Table structure for table `core_knowledge_documents`
--

DROP TABLE IF EXISTS `core_knowledge_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `core_knowledge_documents` (
  `id` int NOT NULL AUTO_INCREMENT,
  `domain` enum('CS','SALES','DOCTOR') NOT NULL,
  `title` varchar(255) NOT NULL,
  `category` varchar(64) NOT NULL DEFAULT 'GENERAL',
  `doc_form` enum('qa_model','text_model','hierarchical_model') NOT NULL DEFAULT 'qa_model',
  `tags` json DEFAULT NULL,
  `status` enum('ACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE',
  `current_version_id` int DEFAULT NULL,
  `created_by` varchar(128) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_core_knowledge_documents_id` (`id`),
  KEY `ix_core_knowledge_documents_category` (`category`),
  KEY `ix_core_knowledge_documents_doc_form` (`doc_form`)
) ENGINE=InnoDB AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
